{
  "apiVersion": 1,
  "type": "hook.detail",
  "package": "@astryxdesign/core",
  "data": {
    "name": "useTableColumnResize",
    "subComponentOf": "Table",
    "displayName": "useTableColumnResize",
    "description": "Hook that returns a TablePlugin adding draggable resize handles to column header borders. Supports pointer + keyboard (WAI-ARIA window splitter) resizing, RTL, per-column min/max widths, and proportional-column preservation (resizes the neighbor so the table stays full-width). Commits widths on release.",
    "props": [
      {
        "name": "columnWidths",
        "type": "Record<string, number>",
        "description": "Controlled pixel-width overrides keyed by column key. When a key is present it overrides the column's declared width."
      },
      {
        "name": "onColumnResizeEnd",
        "type": "(updates: Record<string, number>) => void",
        "description": "Called when a resize completes (pointerup / Enter). Receives a map of every column key whose width changed; merge it into your columnWidths state."
      },
      {
        "name": "minWidth",
        "type": "number",
        "description": "Global minimum column width in pixels during resize. Overrides per-column defaults when set."
      },
      {
        "name": "maxWidth",
        "type": "number",
        "description": "Global maximum column width in pixels during resize.",
        "default": "Infinity"
      },
      {
        "name": "columns",
        "type": "TableColumn<T>[]",
        "description": "Column definitions, needed to derive per-column min widths and detect proportional vs pixel columns for neighbor/last-column resize behavior."
      }
    ]
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
